mapper.select:
SELECT id, parent_id, permission_name, permission_type, perms, path, component, icon, order_num, visible, status, del_flag, api_method, api_path, create_by, create_time, update_by, update_time, remark FROM sys_permission WHERE del_flag = 0
AND status = #{status}
AND visible = #{visible}
AND permission_type = #{permissionType}
AND permission_type IN
#{type}
AND permission_name LIKE CONCAT('%', #{permissionName}, '%')
ORDER BY order_num ASC, create_time ASC
